from typing import Literal, NotRequired, TypedDict

class ReviewBounds(TypedDict):
    x: float
    y: float
    width: float
    height: float

class ReviewCell(TypedDict):
    id: str
    pageIndex: int
    bounds: ReviewBounds
    text: str
    label: str
    column: str
    value: str
    dash: bool
    origin: Literal["scan", "manual"]

class ReviewTerm(TypedDict):
    cellId: str
    coefficient: Literal[-1, 1]

class ReviewEvaluation(TypedDict):
    state: Literal["exact-match", "difference", "not-evaluable"]
    sum: str
    delta: str
    reason: str

class ReviewEquation(TypedDict):
    id: str
    regionId: str
    targetId: str
    terms: list[ReviewTerm]
    axis: Literal["vertical", "cross", "manual"]
    origin: Literal["detected", "manual"]
    decision: Literal["unreviewed", "accepted", "rejected", "deferred"]
    evaluation: ReviewEvaluation
    issue: Literal["open", "explained", "resolved"]
    note: str
    signature: str

class ReviewRegion(TypedDict):
    id: str
    pageIndex: int
    bounds: ReviewBounds
    label: str

class ReviewCorrection(TypedDict):
    cellId: str
    value: str
    reason: str

class ReviewRevision(TypedDict):
    revision: int
    at: str
    equations: list[ReviewEquation]
    corrections: list[ReviewCorrection]
    evidence: list[ReviewCell]
    reviewedPages: list[int]

class ReviewArchive(TypedDict):
    scanId: str
    geometryFingerprint: str
    revision: int
    evidence: list[ReviewCell]
    regions: list[ReviewRegion]
    equations: list[ReviewEquation]
    corrections: list[ReviewCorrection]
    history: list[ReviewRevision]
    reviewedPages: list[int]

class ReviewWorkspace(TypedDict):
    version: Literal[1]
    documentId: str
    scanId: str
    geometryFingerprint: str
    pageCount: int
    revision: int
    evidence: list[ReviewCell]
    regions: list[ReviewRegion]
    equations: list[ReviewEquation]
    corrections: list[ReviewCorrection]
    history: list[ReviewRevision]
    archives: list[ReviewArchive]
    reviewedPages: list[int]

class ReviewDraft(TypedDict):
    regionId: str
    targetId: str
    terms: list[ReviewTerm]
    axis: Literal["vertical", "cross", "manual"]

class ReviewOperation(TypedDict):
    kind: Literal["equation", "decision", "correction", "value", "issue", "restore", "page"]
    equationId: NotRequired[str]
    equation: NotRequired[ReviewDraft]
    equationIds: NotRequired[list[str]]
    decision: NotRequired[Literal["unreviewed", "accepted", "rejected", "deferred"]]
    correction: NotRequired[ReviewCorrection]
    cell: NotRequired[ReviewCell]
    issue: NotRequired[Literal["open", "explained", "resolved"]]
    note: NotRequired[str]
    revision: NotRequired[int]
    pageIndex: NotRequired[int]
    reviewed: NotRequired[bool]

class ReviewRequest(TypedDict):
    type: Literal["reconcile-review-request"]
    version: Literal[1]
    requestId: str
    pdfId: str
    mode: Literal["load", "preview", "commit"]
    scanId: str
    expectedRevision: int
    operations: list[ReviewOperation]

class ReviewResponse(TypedDict):
    type: Literal["reconcile-review-response"]
    version: Literal[1]
    requestId: str
    pdfId: str
    status: Literal["loaded", "preview", "saved", "error"]
    workspace: NotRequired[ReviewWorkspace]
    evaluation: NotRequired[ReviewEvaluation]
    error: NotRequired[str]

class ReviewWorkerJob(TypedDict):
    job_id: str
    command: Literal["reconcile-review"]
    request: ReviewRequest
    model_base64: str
    values_base64: str
    review_base64: str

class ReviewWorkerResult(TypedDict):
    job_id: str
    status: Literal["success"]
    response: ReviewResponse
    review_base64: str

